import{_ as s,o as t,c as a,a2 as o}from"./chunks/framework.DT_qyuxR.js";const m=JSON.parse('{"title":"Les Masques","description":"","frontmatter":{},"headers":[],"relativePath":"gitbook/regles/04-masques.md","filePath":"gitbook/regles/04-masques.md"}'),i={name:"gitbook/regles/04-masques.md"};function r(u,e,n,l,d,c){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="les-masques" tabindex="-1">Les Masques <a class="header-anchor" href="#les-masques" aria-label="Permalink to &quot;Les Masques&quot;">​</a></h1><h2 id="concept" tabindex="-1">Concept <a class="header-anchor" href="#concept" aria-label="Permalink to &quot;Concept&quot;">​</a></h2><p>Chaque joueur porte un <strong>Masque</strong> unique qui détermine :</p><ul><li>Ses <strong>PV maximums</strong> (points de vie).</li><li>Son <strong>Attaque de Combat</strong> (dégâts fixes en Duel).</li><li>Sa <strong>capacité de Jour</strong> (pouvoir utilisé pendant la phase de Jour).</li><li>Sa <strong>capacité de Nuit</strong> (pouvoir utilisé pendant la phase de Nuit).</li><li>Son <strong>passif</strong> (effet déclenché automatiquement).</li></ul><p>Le masque est la seule chose que les autres joueurs voient. Votre identité réelle (votre nom de joueur) et votre camp restent secrets.</p><h2 id="les-pv-secrets" tabindex="-1">Les PV secrets <a class="header-anchor" href="#les-pv-secrets" aria-label="Permalink to &quot;Les PV secrets&quot;">​</a></h2><h3 id="principe" tabindex="-1">Principe <a class="header-anchor" href="#principe" aria-label="Permalink to &quot;Principe&quot;">​</a></h3><ul><li>Chaque masque a un nombre de <strong>PV maximums</strong> (fixe, défini par le masque).</li><li>Les <strong>PV actuels restent secrets</strong> : seul le total de dégâts reçus est public.</li><li>Les joueurs ne connaissent que leurs propres PV.</li><li>Quand un masque se brise (PV ≤ 0), le joueur est K.O.</li></ul><h3 id="pourquoi-des-pv-secrets" tabindex="-1">Pourquoi des PV secrets ? <a class="header-anchor" href="#pourquoi-des-pv-secrets" aria-label="Permalink to &quot;Pourquoi des PV secrets ?&quot;">​</a></h3><p>C&#39;est le cœur de la stratégie : vous ne savez pas si un masque est à bout ou sain. Accuser un joueur à 1 PV est risqué — il peut être à bout ou à pleine vie. Défier un joueur en Duel est un pari.</p><h3 id="le-grimoire-des-masques" tabindex="-1">Le Grimoire des Masques <a class="header-anchor" href="#le-grimoire-des-masques" aria-label="Permalink to &quot;Le Grimoire des Masques&quot;">​</a></h3><p>Le <strong>Grimoire</strong> est un document consultable par tous les joueurs (via leur panneau joueur en MP). Il contient :</p><ul><li>La liste de tous les masques du jeu.</li><li>Les PV maximums de chaque masque.</li><li>Les descriptions des capacités et passifs.</li></ul><blockquote><p><strong>Astuce</strong> : mémoriser les PV max des masques est essentiel pour évaluer les menaces.</p></blockquote><h2 id="le-bris-de-masque" tabindex="-1">Le bris de masque <a class="header-anchor" href="#le-bris-de-masque" aria-label="Permalink to &quot;Le bris de masque&quot;">​</a></h2><h3 id="quand-un-masque-se-brise" tabindex="-1">Quand un masque se brise ? <a class="header-anchor" href="#quand-un-masque-se-brise" aria-label="Permalink to &quot;Quand un masque se brise ?&quot;">​</a></h3><p>Un masque se brise quand ses PV tombent à <strong>0 ou moins</strong>.</p><h3 id="que-se-passe-t-il" tabindex="-1">Que se passe-t-il ? <a class="header-anchor" href="#que-se-passe-t-il" aria-label="Permalink to &quot;Que se passe-t-il ?&quot;">​</a></h3><ol><li>L&#39;<strong>identité du joueur est révélée</strong> dans le salon général (son nom de masque).</li><li>Le <strong>camp n&#39;est PAS révélé</strong>.</li><li>Le joueur peut laisser une <strong>dernière rumeur</strong> (message public de max 200 caractères).</li><li>Le joueur quitte la partie (il ne peut plus agir).</li></ol><h3 id="exception-metamorphose-sans-visage" tabindex="-1">Exception : Métamorphose (Sans-Visage) <a class="header-anchor" href="#exception-metamorphose-sans-visage" aria-label="Permalink to &quot;Exception : Métamorphose (Sans-Visage)&quot;">​</a></h3><p>Si un joueur portant le masque du Sans-Visage est métamorphosé et que son masque se brise, c&#39;est le <strong>masque copié</strong> qui est révélé à la place de son identité réelle.</p><h2 id="choix-du-masque" tabindex="-1">Choix du masque <a class="header-anchor" href="#choix-du-masque" aria-label="Permalink to &quot;Choix du masque&quot;">​</a></h2><h3 id="pool-de-choix" tabindex="-1">Pool de choix <a class="header-anchor" href="#pool-de-choix" aria-label="Permalink to &quot;Pool de choix&quot;">​</a></h3><p>Au début de la partie, chaque joueur reçoit un <strong>pool de masques</strong> parmi lesquels il doit en choisir un. Le pool est déterminé par l&#39;identité (rôle) du joueur.</p><h3 id="processus" tabindex="-1">Processus <a class="header-anchor" href="#processus" aria-label="Permalink to &quot;Processus&quot;">​</a></h3><ol><li>Le bot envoie à chaque joueur (en MP) son pool de masques.</li><li>Le joueur choisit un masque dans son pool.</li><li>Le masque choisi est <strong>secret</strong> — les autres joueurs ne voient pas votre choix.</li></ol><h3 id="strategie-du-choix" tabindex="-1">Stratégie du choix <a class="header-anchor" href="#strategie-du-choix" aria-label="Permalink to &quot;Stratégie du choix&quot;">​</a></h3><p>Choisir un masque, c&#39;est choisir :</p><ul><li><strong>Sa durabilité</strong> : un masque avec beaucoup de PV survit plus longtemps.</li><li><strong>Sa capacité de Jour</strong> : certains masques ont des pouvoirs offensifs, d&#39;autres informationnels.</li><li><strong>Sa capacité de Nuit</strong> : les actions de Nuit sont plus puissantes mais plus risquées.</li><li><strong>Son passif</strong> : certains passifs sont dévastateurs, d&#39;autres sont subtils.</li></ul><h2 id="styles-de-masques" tabindex="-1">Styles de masques <a class="header-anchor" href="#styles-de-masques" aria-label="Permalink to &quot;Styles de masques&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Style</th><th>Description</th><th>Exemples</th></tr></thead><tbody><tr><td><strong>Tank</strong></td><td>PV élevés, dégâts réduits, résistant</td><td>Inflexible, Rocher, Épine</td></tr><tr><td><strong>Offensif</strong></td><td>Dégâts élevés, PV moyens, agressif</td><td>Rage, Incendie, Sacrifice</td></tr><tr><td><strong>Assassin</strong></td><td>Dégâts ciblés, PV faibles, élimination</td><td>Poursuite, Souffrance, Maestro</td></tr><tr><td><strong>Information</strong></td><td>Capacités de révélation, utility</td><td>Chirurgical, Medium, Sans-Visage</td></tr><tr><td><strong>Support</strong></td><td>Soin, protection, buff d&#39;alliés</td><td>Vampire, Empathique</td></tr></tbody></table><blockquote><p><strong>Note</strong> : le style est une indication, pas une restriction. Un masque &quot;Tank&quot; peut jouer agressivement, et vice versa.</p></blockquote>',32)])])}const h=s(i,[["render",r]]);export{m as __pageData,h as default};
